#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events sharing an event_id, write deduped.jsonl."""

import json

def main() -> None:
    seen: set[str] = set()
    with open("events.jsonl") as inf, open("deduped.jsonl", "w") as outf:
        for line in inf:
            line = line.rstrip("\n")
            if not line:
                continue
            obj = json.loads(line)
            eid = obj["event_id"]
            if eid in seen:
                continue
            seen.add(eid)
            outf.write(line + "\n")

if __name__ == "__main__":
    main()

