#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digest per file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_digest(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}
    # Walk release/ recursively, sorting for deterministic output
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            # Relative path from repo root (e.g. "release/VERSION")
            rel_path = str(path.relative_to(RELEASE_DIR.parent))
            manifest[rel_path] = sha256_digest(path)

    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n"
    )
    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

