"""Generate manifest.json mapping release/ files to SHA-256 hex digests."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(filepath: Path) -> str:
    """Return the SHA-256 hex digest of *filepath*."""
    h = hashlib.sha256()
    with filepath.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        msg = f"release directory not found: {RELEASE_DIR}"
        raise SystemExit(msg)

    manifest: dict[str, str] = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel = path.relative_to(RELEASE_DIR)
            manifest[str(rel)] = sha256_digest(path)

    with MANIFEST_PATH.open("w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"manifest.json written with {len(manifest)} entries")


if __name__ == "__main__":
    main()

