import re

REPORTS_DIR = "reports"


def report_key(filename: str) -> int:
    """Extract the numeric part from 'report-<n>.txt' for natural ordering."""
    m = re.search(r"report-(\d+)", filename)
    return int(m.group(1)) if m else 0


def main() -> None:
    if not os.path.isdir(REPORTS_DIR):
        return

    files = [
        f for f in os.listdir(REPORTS_DIR)
        if os.path.isfile(os.path.join(REPORTS_DIR, f))
    ]
    files.sort(key=report_key)
    for f in files:
        print(f)


if __name__ == "__main__":
    main()
