import sys
import os
import time
from datetime import datetime, timezone, timedelta

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
APP_LOG = os.path.join(SCRIPT_DIR, 'app.log')
ARCHIVE_LOG = os.path.join(SCRIPT_DIR, 'archive.log')


def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    try:
        return datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print('Usage: python rotate.py AS_OF', file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print('AS_OF must be an integer Unix timestamp.', file=sys.stderr)
        sys.exit(1)

    cutoff_dt = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    if not os.path.isfile(APP_LOG):
        print(f'{APP_LOG} not found.', file=sys.stderr)
        sys.exit(1)

    with open(APP_LOG, 'r') as f:
        lines = f.readlines()

    keep = []
    archive = []

    for line in lines:
        if not line.strip():
            continue
        entry_dt = parse_timestamp(line)
        if entry_dt is None:
            # If we can't parse, keep it (fallback)
            keep.append(line)
        elif entry_dt < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    # Append archived entries to archive.log
    if archive:
        with open(ARCHIVE_LOG, 'a') as f:
            f.writelines(archive)

    # Rewrite app.log with kept entries
    with open(APP_LOG, 'w') as f:
        f.writelines(keep)


if __name__ == '__main__':
    main()

