#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_line(line: str):
    """Parse a log line into (datetime, rest) or None if unparseable."""
    line = line.rstrip("\n")
    try:
        ts = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
        ts = ts.replace(tzinfo=timezone.utc)
        return ts, line
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    log_path = "app.log"
    archive_path = "archive.log"

    # Read all entries
    try:
        with open(log_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {log_path} not found", file=sys.stderr)
        sys.exit(1)

    # Sort into keep and archive buckets, preserving order
    keep_lines = []
    archive_lines = []

    for line in lines:
        parsed = parse_line(line)
        if parsed is None:
            # Unparseable lines stay in app.log
            keep_lines.append(line)
        else:
            entry_dt, _ = parsed
            if entry_dt < cutoff:
                archive_lines.append(line)
            else:
                keep_lines.append(line)

    # Write archive.log (append if exists, create if not)
    try:
        existing_archive = ""
        try:
            with open(archive_path) as f:
                existing_archive = f.read()
        except FileNotFoundError:
            pass

        with open(archive_path, "w") as f:
            if existing_archive:
                f.write(existing_archive)
                if not existing_archive.endswith("\n"):
                    f.write("\n")
            f.writelines(archive_lines)
    except OSError as e:
        print(f"Error writing {archive_path}: {e}", file=sys.stderr)
        sys.exit(1)

    # Rewrite app.log with remaining entries
    try:
        with open(log_path, "w") as f:
            f.writelines(keep_lines)
    except OSError as e:
        print(f"Error writing {log_path}: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

