import sys
from datetime import datetime, timedelta, timezone


def parse_line(line):
    """Parse a log line into (datetime, message) or None if malformed."""
    line = line.rstrip("\n")
    if len(line) < 19 or line[4] != "-" or line[7] != "-" or line[10] != " " or line[13] != ":" or line[16] != ":":
        return None
    try:
        ts = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None
    return ts, line


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of_ts = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    as_of = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff = as_of - timedelta(days=7)

    app_log_path = "app.log"
    archive_log_path = "archive.log"

    try:
        with open(app_log_path, "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep = []
    archive = []

    for line in lines:
        parsed = parse_line(line)
        if parsed is None:
            # Malformed lines are kept in app.log (defensive approach)
            keep.append(line)
